H.background();
// Double-slit interference:  d * sin(theta) = m * lambda   (bright fringes)
// On a distant screen, fringe spacing  dy = lambda * L / d.
const v = H.plot2d({ xMin: -30, xMax: 30, yMin: 0, yMax: 1.25 });
v.grid(); v.axes();
const lam = P.lambda;     // wavelength (nm)
const d = P.d;            // slit separation (micrometers)
const L = P.L;            // slit-to-screen distance (m)
// Position on screen in mm; theta small so sin(theta) ~ y/L.
const lam_m = lam * 1e-9, d_m = d * 1e-6, L_m = L;
function intensity(y_mm) {
  const y = y_mm * 1e-3;
  const theta = Math.atan2(y, L_m);
  const phi = Math.PI * d_m * Math.sin(theta) / lam_m;  // half phase diff
  const c = Math.cos(phi);
  return c * c;   // I/Imax = cos^2(pi d sin / lambda)
}
v.fn(intensity, { color: H.colors.accent, width: 2.5, steps: 400 });
// Fringe spacing (mm): dy = lambda L / d.
const dy = lam_m * L_m / d_m * 1e3;
